import os
import torch


class Config:
    # ==========================================
    # General Settings
    # ==========================================
    SEED = 42
    DEBUG = False  # Set to True to run on a small subset for testing

    # ==========================================
    # File Paths
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the provided script
    TRAIN_METADATA = os.path.join(METADATA_DIR, "train_metadata.csv")
    VALIDATION_METADATA = os.path.join(METADATA_DIR, "validation_metadata.csv")
    TEST_METADATA = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Working directory for caching processed data and model checkpoints
    # Specifically for "idea_3" as per requirements
    WORKING_DIR = "./working/idea_3"

    # Output directory for submission
    OUTPUT_DIR = "./submission"
    SUBMISSION_FILE = os.path.join(OUTPUT_DIR, "submission.csv")

    # ==========================================
    # Data Configuration
    # ==========================================
    IMAGE_SIZE = 256

    # Input channels:
    # 3 channels for Ash Color Composite (Band 11, 14, 15)
    # 3 channels for Temporal Difference (Frame t - Frame t-1)
    IN_CHANNELS = 6

    # ==========================================
    # Model Hyperparameters
    # ==========================================
    ENCODER_NAME = "resnet18"
    ENCODER_WEIGHTS = "imagenet"

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    BATCH_SIZE = 64  # A100 40GB can handle large batches for ResNet18
    NUM_WORKERS = 8  # 12 vCPUs available
    EPOCHS = 20  # As per strategy to prevent overfitting on sparse data

    LEARNING_RATE = 3e-4
    WEIGHT_DECAY = 1e-4

    # Loss Weights
    # Total Loss = Loss_Seg + CLS_WEIGHT * Loss_Cls
    CLS_WEIGHT = 0.5

    # Scheduler
    T_MAX = EPOCHS  # For CosineAnnealingLR

    # Early Stopping
    PATIENCE = 5

    # ==========================================
    # Inference / Post-processing
    # ==========================================
    # Threshold for pixel-level probability mask
    PIXEL_THRESHOLD = 0.5

    # Threshold for image-level classification gate
    # If image_prob < CLS_THRESHOLD, the entire mask is zeroed out
    CLS_THRESHOLD = 0.5

    # ==========================================
    # Hardware
    # ==========================================
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    @classmethod
    def setup(cls):
        """
        Ensures necessary directories exist.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.OUTPUT_DIR, exist_ok=True)
